6	// Each view window covers a fixed number of the roller's own windows and
7	// carries statistics merged from them; no raw samples are re-read. A View
8	// is a snapshot of the moment it was derived: samples filed, backfilled,
9	// or merged into the roller afterwards do not alter it.
10	//
11	// All methods are safe to call concurrently from multiple goroutines.
12	type View struct {
13		// window is the coarse window size: the roller's window size times
14		// the factor the view was derived with. windows is fixed at
15		// derivation and read without a lock.
16		window  time.Duration
17		windows []Window
