21	// times wider than the roller's own, aligned to integer multiples of the
22	// coarser size since the Unix epoch, left-closed and right-open exactly
23	// like the roller's windows. Each coarse window merges the statistics of
24	// the roller windows it covers: counts and sums add, minimums take the
25	// smaller, maximums take the larger. A factor of 1 yields a view
26	// window-for-window identical to the roller's own.
27	//
28	// Rollup panics with "rollup: bad factor" if factor is not positive. It
29	// is a pure read: the roller's statistics and its most-recent marker are
30	// untouched, and concurrent adds, batches, backfills, and merges proceed
31	// as usual — the view observes one consistent snapshot of the roller.
32	func (r *Roller) Rollup(factor int) *View {
33		if factor <= 0 {
34			panic("rollup: bad factor")
35		}
36		coarse := time.Duration(factor) * r.window
37		w := coarse.Nanoseconds()
38	
39		r.mu.RLock()
40		defer r.mu.RUnlock()
41		fine := r.buckets
42		if len(r.back) != 0 {
43			fine = mergeWindows(r.buckets, r.back)
44		}
45		// The coarse start is monotone in the fine start, so covered windows
46		// are consecutive and the whole derivation is one linear pass with a
47		// single output allocation bounded by the number of fine windows.
48		windows := make([]Window, 0, len(fine))
49		for _, f := range fine {
50			start := alignStart(f.Start, w)
51			if n := len(windows); n != 0 && windows[n-1].Start.Equal(start) {
52				cur := &windows[n-1]
53				cur.Count = satAdd(cur.Count, f.Count)
54				cur.Sum += f.Sum
55				if f.Min < cur.Min {
56					cur.Min = f.Min
57				}
58				if f.Max > cur.Max {
59					cur.Max = f.Max
60				}
61			} else {
62				windows = append(windows, Window{
63					Start: start,
64					Count: f.Count,
65					Sum:   f.Sum,
66					Min:   f.Min,
67					Max:   f.Max,
68				})
69			}
70		}
71		return &View{window: coarse, windows: windows}
72	}
