75	// the same exact-match rule as the roller's Window. A start no coarse
76	// window begins at yields the zero Window and no error; whether the window
77	// exists is told from its sample count. The returned Window is a copy and
78	// stays valid no matter what is filed into the roller afterwards.
79	func (v *View) Window(start time.Time) Window {
80		if i, ok := windowIndex(v.windows, start); ok {
81			return v.windows[i]
82		}
